package dev.risingheroes.core;

import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;

class QuirkResourcesTest {
    private HeroProfile kit(String id){var p=new HeroProfile();HeroRules.assign(p,id);return p;}
    @ParameterizedTest @ValueSource(strings={"explosion","half_cold_half_hot","hardening","electrification","blueflame","umbrakinesis","kinetic_reservoir"})
    void eachKitHasRealStartersAndOnlyOwnMoves(String id){var p=kit(id);assertEquals(Kits.get(id).starters().size(),p.currentUnlocks().size());assertFalse(p.slots.get(0).isBlank());assertFalse(p.slots.get(4).isBlank());assertTrue(p.slots.get(5).isBlank());for(String move:p.slots)if(!move.isBlank())assertEquals(id,Kits.owner(move).id());}
    @Test void catalogueOwnsEveryMoveExactlyOnce(){assertEquals(57,Catalog.moves().size());Set<String> ids=new HashSet<>();for(var k:Kits.all()){assertTrue(k.moves().size()>=6&&k.moves().size()<=10);for(String move:k.moves())assertTrue(ids.add(move));}assertEquals(Catalog.moves().keySet(),ids);}
    @Test void alternatingThermalStartersBalancesTemperatureWithoutRefreshingCooldowns(){var p=kit("half_cold_half_hot");HeroRules.reserveCast(p,0,100,false,false,false);assertEquals(-15,QuirkResources.primary(p));long cooldown=p.cooldowns.get("ice_shot");HeroRules.reserveCast(p,1,200,false,false,false);assertEquals(0,QuirkResources.primary(p));assertEquals(cooldown,p.cooldowns.get("ice_shot"));assertEquals(74,p.stamina);}
    @Test void thermalExtremesRejectSameSideButAllowTheOppositeSide(){var p=kit("half_cold_half_hot");p.resources.put("temperature",95.0);assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,1,100,false,false,false));assertEquals(100,p.stamina);HeroRules.reserveCast(p,0,100,false,false,false);assertEquals(80,QuirkResources.primary(p));}
    @Test void balancedTechniquesAndUnderwaterRulesAreEnforced(){var p=kit("half_cold_half_hot");HeroRules.testingLoadout(p);p.slots.set(0,"thermal_shock");p.resources.put("temperature",40.0);assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,false,false));p.resources.put("temperature",0.0);p.slots.set(0,"flame_jet");assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,100,false,false,true));p.slots.set(0,"ice_shot");assertDoesNotThrow(()->HeroRules.reserveCast(p,0,100,false,false,true));}
    @Test void fatigueIsIndependentOfArchivedBlastStrainAndCannotOverflow(){var p=kit("hardening");p.strain=99;HeroRules.reserveCast(p,0,100,false,false,false);assertEquals(8,QuirkResources.primary(p));assertEquals(99,p.strain);var tired=kit("hardening");tired.resources.put("fatigue",95.0);assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(tired,0,100,false,false,false));assertEquals(100,tired.stamina);}
    @Test void heavyDischargeSpendsChargeAndPreservesOverloadAcrossAssignment(){var p=kit("electrification");HeroRules.testingLoadout(p);p.resources.put("overload",60.0);HeroRules.reserveCast(p,5,100,false,false,false);assertEquals(40,QuirkResources.primary(p));assertEquals(100,QuirkResources.overload(p));assertEquals(220,p.overloadUntil);HeroRules.assign(p,"hardening");assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,0,120,false,false,false));assertEquals(220,p.exertionUntil);assertEquals(40,p.resources.get("charge"));}
    @Test void spoofedCrossKitUnlockCannotBeEquippedOrCast(){var p=kit("hardening");p.currentUnlocks().add("ice_shot");assertThrows(IllegalArgumentException.class,()->HeroRules.equip(p,1,"ice_shot",100));p.slots.set(1,"ice_shot");assertThrows(IllegalArgumentException.class,()->HeroRules.reserveCast(p,1,100,false,false,false));assertEquals(100,p.stamina);}
    @Test void newKitPracticeGrantsOnlyItsFirstTrainingMasteryAndNoDuplicateCurrency(){var p=kit("half_cold_half_hot");p.schoolStage=4;for(var mission:MissionCatalog.all())if(mission.path().equals("independent")){MissionRules.start(p,mission.id(),100);while(!p.mission.completed){var s=MissionRules.stage(p);for(int i=0;i<s.count();i++)MissionRules.witness(p,p.mission.session,s.type(),s.role(),s.id()+i);}MissionRules.leave(p);}assertTrue(p.currentUnlocks().containsAll(Kits.get(p.quirk).moves()));int credits=p.credits;HeroRules.assign(p,"hardening");MissionRules.start(p,"neighbourhood_watch",100);while(!p.mission.completed){var s=MissionRules.stage(p);for(int i=0;i<s.count();i++)MissionRules.witness(p,p.mission.session,s.type(),s.role(),s.id()+i);}assertEquals(credits,p.credits);assertTrue(p.mastery()>0);assertEquals(0,p.licence);}
}
